record.field:
# ตรวจสอบคณะกรรมการกำหนดคุณลักษณะเฉพาะฯ สำหรับมูลค่า >= 100,000
if object.estimated_cost >= 100000:
    if len(object.tor_committee_ids) < 3:
        failed = True
        message = "คณะกรรมการกำหนดคุณลักษณะเฉพาะร่างขอบเขตงานต้องมีอย่างน้อย 3 คน เนื่องจากมูลค่าโครงการ >= 100,000 (ปัจจุบันมี %d คน)" % len(object.tor_committee_ids)

# ตรวจสอบคณะกรรมการกำหนดราคากลาง สำหรับมูลค่า >= 100,000
if object.estimated_cost >= 100000:
    if len(object.price_determine_committee_ids) < 3:
        failed = True
        message = "คณะกรรมการกำหนดราคากลางต้องมีอย่างน้อย 3 คน เนื่องจากมูลค่าโครงการ >= 100,000 (ปัจจุบันมี %d คน)" % len(object.price_determine_committee_ids)

# ตรวจสอบคณะกรรมการพิจารณาผล สำหรับมูลค่า >= 100,000
if object.estimated_cost >= 100000:
    if len(object.evaluation_committee_ids) < 3:
        failed = True
        message = "คณะกรรมการพิจารณาผลต้องมีอย่างน้อย 3 คน เนื่องจากมูลค่าโครงการ >= 100,000 (ปัจจุบันมี %d คน)" % len(object.evaluation_committee_ids)

# ตรวจสอบ committee ตามมูลค่าโครงการ
errors = []

if object.estimated_cost < 100000:
    # มูลค่าต่ำ: ตรวจสอบเฉพาะ Section 1
    if len(object.work_acceptance_committee_ids) < 3:
        errors.append("คณะกรรมการตรวจรับพัสดุต้องมีอย่างน้อย 3 คน (ปัจจุบันมี %d คน)" % len(object.work_acceptance_committee_ids))

elif object.estimated_cost >= 100000:
    # มูลค่าสูง: ตรวจสอบทั้ง 4 Sections
    if len(object.work_acceptance_committee_ids) < 3:
        errors.append("คณะกรรมการตรวจรับพัสดุต้องมีอย่างน้อย 3 คน (ปัจจุบันมี %d คน)" % len(object.work_acceptance_committee_ids))

    if len(object.tor_committee_ids) < 3:
        errors.append("คณะกรรมการกำหนดคุณลักษณะเฉพาะฯ ต้องมีอย่างน้อย 3 คน (ปัจจุบันมี %d คน)" % len(object.tor_committee_ids))

    if len(object.price_determine_committee_ids) < 3:
        errors.append("คณะกรรมการกำหนดราคากลางต้องมีอย่างน้อย 3 คน (ปัจจุบันมี %d คน)" % len(object.price_determine_committee_ids))

    if len(object.evaluation_committee_ids) < 3:
        errors.append("คณะกรรมการพิจารณาผลต้องมีอย่างน้อย 3 คน (ปัจจุบันมี %d คน)" % len(object.evaluation_committee_ids))

if errors:
    failed = True
    if object.estimated_cost < 100000:
        message = "โครงการมูลค่าต่ำกว่า 100,000: " + "\n".join(errors)
    else:
        message = "โครงการมูลค่า 100,000 ขึ้นไป: " + "\n".join(errors)

# ตรวจสอบการซ้ำของสมาชิกคณะกรรมการ (เฉพาะมูลค่าสูงที่มีหลาย committee)
if object.estimated_cost >= 100000:
    all_members = []

    # รวบรวม employee_id จากทุก committee
    for member in object.work_acceptance_committee_ids:
        if member.employee_id:
            all_members.append(member.employee_id.id)

    for member in object.tor_committee_ids:
        if member.employee_id:
            all_members.append(member.employee_id.id)

    for member in object.price_determine_committee_ids:
        if member.employee_id:
            all_members.append(member.employee_id.id)

    for member in object.evaluation_committee_ids:
        if member.employee_id:
            all_members.append(member.employee_id.id)

    # ตรวจสอบการซ้ำ
    unique_members = set(all_members)
    if len(all_members) != len(unique_members):
        failed = True
        duplicates = len(all_members) - len(unique_members)
        message = "พบสมาชิกคณะกรรมการซ้ำกันในหลายคณะ (ซ้ำ %d ครั้ง) กรุณาตรวจสอบและแก้ไข\nโครงการมูลค่าสูงไม่ควรมีสมาชิกคณะกรรมการคนเดียวกันใน multiple committees" % duplicates
